import{_ as t,o as i,c as s,a6 as r}from"./chunks/framework.CCKCzdWs.js";const n="/screenshots/jetbrains-failures.png",u=JSON.parse('{"title":"JetBrains plugin","description":"The Piwi plugin for WebStorm, IntelliJ IDEA Ultimate, Rider and the other JetBrains IDEs with the LSP API: what it needs, and where it shows the failures, the lines above the code, the status bar and the recording controls.","frontmatter":{"title":"JetBrains plugin","description":"The Piwi plugin for WebStorm, IntelliJ IDEA Ultimate, Rider and the other JetBrains IDEs with the LSP API: what it needs, and where it shows the failures, the lines above the code, the status bar and the recording controls.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/jetbrains.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/jetbrains.html"}],["meta",{"property":"og:title","content":"JetBrains plugin | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The Piwi plugin for WebStorm, IntelliJ IDEA Ultimate, Rider and the other JetBrains IDEs with the LSP API: what it needs, and where it shows the failures, the lines above the code, the status bar and the recording controls."}]]},"headers":[],"relativePath":"features/jetbrains.md","filePath":"features/jetbrains.md","lastUpdated":1793045663000}'),o={name:"features/jetbrains.md"};function a(h,e,l,d,g,c){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="jetbrains-plugin" tabindex="-1">JetBrains plugin <a class="header-anchor" href="#jetbrains-plugin" aria-label="Permalink to &quot;JetBrains plugin&quot;">​</a></h1><p>The Piwi plugin brings the <a href="./editors.html">editor extensions</a> to the JetBrains IDEs with the LSP API: WebStorm, IntelliJ IDEA Ultimate, Rider and the others, from 2024.1. It runs the same editor service as the VS Code extension, so the editor pages describe it too, with the JetBrains names of each action. This page lists what the plugin needs, and where it shows what VS Code shows differently.</p><figure><img src="'+n+'" alt="WebStorm: the failing tests tinted in the spec, the Piwi tool window below with the run&#39;s failures"><figcaption>WebStorm: the latest run&#39;s failures in the Piwi tool window, a local run laid over them, the failing tests tinted above.</figcaption></figure><h2 id="install-and-start" tabindex="-1">Install and start <a class="header-anchor" href="#install-and-start" aria-label="Permalink to &quot;Install and start&quot;">​</a></h2><p>Install <strong>Piwi</strong> from <strong>Settings → Plugins</strong> or the <strong><a href="https://plugins.jetbrains.com/plugin/34674-piwi" target="_blank" rel="noreferrer">JetBrains Marketplace ↗</a></strong>. IntelliJ IDEA Community Edition and Android Studio lack the LSP API the plugin needs.</p><p>The plugin starts the editor service with the project&#39;s Node.js interpreter, 20 or later (<strong>Settings → Languages &amp; Frameworks → Node.js</strong>, which the status bar opens when it is missing or older), once it finds a Playwright config within four folders of the project&#39;s (in Rider, the solution&#39;s) or of its Git root, and looks again on <strong>Tools → Piwi → Refresh</strong>. It reads the connection the reporter already uses; otherwise, <strong>Settings → Tools → Piwi</strong> signs you in with the browser: <a href="./editor-connection.html">Editor connection</a>.</p><p>The first trusted project with a Playwright config that nothing connects yet shows one notification, once per installation, with <strong>Connect…</strong>, <strong>Open the Failures</strong> and <strong>Learn More</strong>.</p><h2 id="where-things-are" tabindex="-1">Where things are <a class="header-anchor" href="#where-things-are" aria-label="Permalink to &quot;Where things are&quot;">​</a></h2><p>The IDE&#39;s LSP client shows warnings, quick fixes (Alt+Enter) and hover in open files; the rest is native, and every action is under <strong>Tools → Piwi</strong>:</p><ul><li><strong>The Piwi tool window</strong> names the connection and holds the <a href="./editor-failures.html#the-failures-view">failures view</a>, since the IDE highlights open files only.</li><li><strong>Code Vision</strong> shows the lines above files, locators and failing lines; each test&#39;s result is in the gutter, and a click on its icon opens the test in the dashboard.</li><li><strong>The status bar</strong> shows the latest run, or the run in progress, of the selected file&#39;s Playwright config, with an icon for its state and the error color while its tests fail; a click opens a menu of the actions, led by what the item calls for: <a href="./editor-runs.html#the-status-bar">the status bar</a>.</li><li><strong>The editor&#39;s context menu</strong> of a spec holds <strong>Run the Test at the Caret</strong>, <strong>Verify the Test at the Caret ×3</strong> and <strong>Run This Spec</strong>.</li><li><strong><a href="./editor-recording.html">Recording</a></strong> starts from <strong>Record Here</strong>, Alt+Enter or Alt+Insert, and <strong>File → New → Record a New Test File…</strong>; its controls are in a banner above the editor.</li><li><strong>The severity of a failure</strong>: <strong>Settings → Tools → Piwi → Runs</strong> chooses it (<a href="./editor-failures.html#ci-failures-in-the-problems-panel">CI failures in the Problems panel</a>); an information shows as a weak warning.</li><li><strong>Piwi&#39;s MCP server for the agent</strong>: <strong>Settings → Tools → Piwi → AI Assistant</strong> chooses whether the copied configuration holds the IDE&#39;s key or has the agent sign in through the browser (<a href="./editors.html#piwi-s-mcp-server-for-the-agent">Piwi&#39;s MCP server for the agent</a>).</li><li><strong><a href="./ide-integration.html#jetbrains-ides-the-piwi-plugin">Open in IDE</a></strong>: a path clicked in the dashboard or the desktop app opens at its line, with nothing to set up.</li></ul><p>The shortcuts are those of VS Code (<a href="./editors.html#commands">Commands</a>); <strong>Settings → Keymap</strong> changes them (search <code>Piwi</code>).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editors.html">Editor extensions</a>: what the editor shows from your suite, in both editors.</li><li><a href="./editor-connection.html">Editor connection</a>: the instance the plugin reads, and its key.</li><li><a href="./ide-integration.html">Open in IDE</a>: open a path from the dashboard in the IDE.</li></ul>',13)])])}const f=t(o,[["render",a]]);export{u as __pageData,f as default};
